actions.script:
// Disable any existing active config
ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").list().each {
    it.set("enabled", "N").store()
}

// Find or create config record
def existing = ec.entity.find("moqui.adk.AdkAgentConfig").condition("agentName", agentName).one()
if (existing) {
    existing.set("modelName", modelName)
    existing.set("systemPrompt", systemPrompt)
    existing.set("enabled", "Y")
    if (apiKey) existing.set("apiKey", apiKey)
    existing.store()
} else {
    ec.entity.makeValue("moqui.adk.AdkAgentConfig")
        .setSequencedIdPrimary()
        .set("agentName", agentName)
        .set("modelName", modelName)
        .set("apiKey", apiKey ?: "")
        .set("systemPrompt", systemPrompt ?: "You are a helpful assistant for the GrowERP system.")
        .set("enabled", "Y")
        .create()
}
